/*  直接插入排序 */
void Insert_Sort(int a[], int n) {
  int i, j, insertVal;
  for (i = 1; i < n; i++) {
    if (a[i - 1] > a[i]) {
      insertVal = a[i];
      for (j = i - 1; j >= 0 && a[j] > insertVal; j--) {
        a[j + 1] = a[j];
      }
      a[j + 1] = insertVal;
    }
  }
}
